/**
 * FFI-compatible error type for composer operations.
 */
sealed class AlgoKitComposerException : kotlin.Exception() {
  class InvalidAddress(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class InvalidByteLength(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class InvalidTxnParams(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class SignerCountMismatch(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class Signing(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class Transact(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class Algod(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class Msgpack(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class SimulateResponseShape(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class InvalidSimulateOptions(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  class SimulationFailed(
    val `errorMsg`: kotlin.String,
  ) : AlgoKitComposerException() {
    override val message
      get() = "errorMsg=${ `errorMsg` }"
  }

  companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AlgoKitComposerException> {
    override fun lift(error_buf: RustBuffer.ByValue): AlgoKitComposerException = FfiConverterTypeAlgoKitComposerError.lift(error_buf)
  }
}

/**
 * @suppress
 */
public object FfiConverterTypeAlgoKitComposerError : FfiConverterRustBuffer<AlgoKitComposerException> {
  override fun read(buf: ByteBuffer): AlgoKitComposerException =
    when (buf.getInt()) {
      1 -> {
        AlgoKitComposerException.InvalidAddress(
          FfiConverterString.read(buf),
        )
      }

      2 -> {
        AlgoKitComposerException.InvalidByteLength(
          FfiConverterString.read(buf),
        )
      }

      3 -> {
        AlgoKitComposerException.InvalidTxnParams(
          FfiConverterString.read(buf),
        )
      }

      4 -> {
        AlgoKitComposerException.SignerCountMismatch(
          FfiConverterString.read(buf),
        )
      }

      5 -> {
        AlgoKitComposerException.Signing(
          FfiConverterString.read(buf),
        )
      }

      6 -> {
        AlgoKitComposerException.Transact(
          FfiConverterString.read(buf),
        )
      }

      7 -> {
        AlgoKitComposerException.Algod(
          FfiConverterString.read(buf),
        )
      }

      8 -> {
        AlgoKitComposerException.Msgpack(
          FfiConverterString.read(buf),
        )
      }

      9 -> {
        AlgoKitComposerException.SimulateResponseShape(
          FfiConverterString.read(buf),
        )
      }

      10 -> {
        AlgoKitComposerException.InvalidSimulateOptions(
          FfiConverterString.read(buf),
        )
      }

      11 -> {
        AlgoKitComposerException.SimulationFailed(
          FfiConverterString.read(buf),
        )
      }

      else -> {
        throw RuntimeException("invalid error enum value, something is very wrong!!")
      }
    }

