        Unit
      }

      is AlgoKitComposerException.Signing -> {
        buf.putInt(5)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }

      is AlgoKitComposerException.Transact -> {
        buf.putInt(6)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }

      is AlgoKitComposerException.Algod -> {
        buf.putInt(7)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }

      is AlgoKitComposerException.Msgpack -> {
        buf.putInt(8)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }

      is AlgoKitComposerException.SimulateResponseShape -> {
        buf.putInt(9)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }

      is AlgoKitComposerException.InvalidSimulateOptions -> {
        buf.putInt(10)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }

      is AlgoKitComposerException.SimulationFailed -> {
        buf.putInt(11)
        FfiConverterString.write(value.`errorMsg`, buf)
        Unit
      }
    }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
  }
}

