/**
 * Encode a simulate request for an already-signed group. Signatures are preserved unless
 * `options.skip_signatures` is set.
 */
@Throws(AlgoKitComposerException::class)
fun `buildSignedSimulateRequest`(
  `signedTransactions`: List<kotlin.ByteArray>,
  `options`: SimulateOptions,
): kotlin.ByteArray =
  FfiConverterByteArray.lift(
    uniffiRustCallWithError(AlgoKitComposerException) { _status ->
      UniffiLib.INSTANCE.uniffi_algokit_composer_ffi_fn_func_build_signed_simulate_request(
        FfiConverterSequenceByteArray.lower(`signedTransactions`),
        FfiConverterTypeSimulateOptions.lower(`options`),
        _status,
      )
    },
  )

