  `txnParams`: List<TxnParams>,
  `composerParams`: ComposerParams,
): List<kotlin.ByteArray> =
  FfiConverterSequenceByteArray.lift(
    uniffiRustCallWithError(AlgoKitComposerException) { _status ->
